const ctx = canvas.getContext('2d');

// Initial angle and angular velocity
let theta0 = 0;
let omega0 = 0;

// Update function for the pendulum motion
function update(t, dt) {
  // Calculate the acceleration using the differential equation
  const alpha = -G/L * Math.sin(theta0);

  // Update the angular velocity and angle
  omega0 += alpha * dt;
  theta0 += omega0 * dt;

  // Wrap the angle around the circle (360 degrees)
  theta0 = theta0 % (2 * Math.PI);
}

// Draw function for the pendulum
function draw() {
  // Clear the canvas
  ctx.clearRect(0, 0, canvas.width, canvas.height);

  // Calculate the pendulum's position
  const x = L * Math.sin(theta0);
  const y = -L * Math.cos(theta0);

  // Draw the pendulum bob
